function parseBig(raw,base){let s=raw.trim().replace(/[,_\s]/g,'');if(!s)throw Error('値を入力してください');if(s.length>512)throw Error('入力が長すぎます');let sign='';if(s[0]==='-'||s[0]==='+'){sign=s[0]==='-'?'-':'';s=s.slice(1)}if(!s)throw Error('数値として読めません');if(base==='auto'){if(/^0b/i.test(s))base='2';else if(/^0x/i.test(s))base='16';else base='10'}if(base==='2'){s=s.replace(/^0b/i,'');if(!/^[01]+$/.test(s))throw Error('2進数は0と1だけで入力してください');return BigInt(sign+'0b'+s)}if(base==='16'){s=s.replace(/^0x/i,'');if(!/^[0-9a-f]+$/i.test(s))throw Error('16進数は0〜9とA〜Fで入力してください');return BigInt(sign+'0x'+s)}if(!/^\d+$/.test(s))throw Error('10進数は0〜9で入力してください');return BigInt(sign+s)}function groupBits(v){const neg=v<0n,s=(neg?-v:v).toString(2),pad=(4-s.length%4)%4+'',x='0'.repeat(Number(pad))+s,parts=x.match(/.{1,4}/g)||[x];return(neg?'-':'')+parts.join(' ')}function initBase(){const input=$('[data-base-input]'),base=$('[data-base-select]'),err=$('[data-error]');const outs={bin:$('[data-out-bin]'),dec:$('[data-out-dec]'),hex:$('[data-out-hex]')};const run=()=>{try{const v=parseBig(input.value,base.value);err.classList.remove('show');outs.bin.textContent=groupBits(v);outs.dec.textContent=v.toString(10);outs.hex.textContent=(v<0n?'-':'')+(v<0n?-v:v).toString(16).toUpperCase();$$('[data-copy-kind]').forEach(b=>b.dataset.copy=outs[b.dataset.copyKind].textContent);once()}catch(e){err.textContent=e.message;err.classList.add('show');Object.values(outs).forEach(x=>x.textContent='—')}};input.addEventListener('input',run);base.addEventListener('change',run);$$('[data-base-example]').forEach(b=>b.onclick=()=>{input.value=b.dataset.baseExample;base.value=b.dataset.baseMode;run()});$$('[data-copy-kind]').forEach(b=>b.onclick=()=>copy(b.dataset.copy||'',b));run()}
function parseIP(s){const a=s.trim().split('.');if(a.length!==4)throw Error('IPv4は 192.168.1.10 のように4つの数字で入力してください');const n=a.map(x=>{if(!/^\d{1,3}$/.test(x))throw Error('IPv4の各部分は0〜255で入力してください');const v=Number(x);if(v<0||v>255)throw Error('IPv4の各部分は0〜255です');return v});return n}const ipToNum=a=>a[0]*16777216+a[1]*65536+a[2]*256+a[3];const numToIP=n=>[Math.floor(n/16777216)%256,Math.floor(n/65536)%256,Math.floor(n/256)%256,n%256].join('.');function initCIDR(){const ip=$('[data-cidr-ip]'),pre=$('[data-cidr-prefix]'),err=$('[data-error]');const run=()=>{try{const a=parseIP(ip.value),p=Number(pre.value);if(!Number.isInteger(p)||p<0||p>32)throw Error('CIDRは0〜32で入力してください');const n=ipToNum(a),size=2**(32-p),net=Math.floor(n/size)*size,bcast=net+size-1;const mask=p===0?0:2**32-2**(32-p),wild=2**32-1-mask,total=size,usable=p===32?1:p===31?2:Math.max(0,total-2),first=p>=31?net:net+1,last=p>=31?bcast:bcast-1;err.classList.remove('show');$('[data-cidr-network]').textContent=numToIP(net)+'/'+p;$('[data-cidr-broadcast]').textContent=numToIP(bcast);$('[data-cidr-mask]').textContent=numToIP(mask);$('[data-cidr-wild]').textContent=numToIP(wild);$('[data-cidr-range]').textContent=numToIP(first)+' – '+numToIP(last);$('[data-cidr-hosts]').textContent=usable.toLocaleString();const bits=a.map(x=>x.toString(2).padStart(8,'0')).join(''),netBits=bits.slice(0,p),hostBits=bits.slice(p),bar=$('[data-bitbar]');bar.innerHTML='<span class="net" style="flex:'+Math.max(p,1)+'">'+esc(netBits||'—')+'</span><span class="host" style="flex:'+Math.max(32-p,1)+'">'+esc(hostBits||'—')+'</span>';$('[data-cidr-summary]').textContent='左から'+p+' bitがネットワーク部、残り'+(32-p)+' bitがホスト部です。'+(p===31?' /31はRFC 3021でポイントツーポイント用途に2アドレスを利用できます。':p===32?' /32は1つのアドレスだけを表します。':'');once()}catch(e){err.textContent=e.message;err.classList.add('show')}};ip.addEventListener('input',run);pre.addEventListener('input',run);$$('[data-prefix]').forEach(b=>b.onclick=()=>{pre.value=b.dataset.prefix;run()});run()}
function initText(){const input=$('[data-text-input]'),total=$('[data-text-total]'),count=$('[data-text-count]'),table=$('[data-char-table]'),allhex=$('[data-text-hex]');const enc=new TextEncoder();const run=()=>{const txt=input.value,bytes=[...enc.encode(txt)],chars=[...txt];total.textContent=bytes.length.toLocaleString()+' byte';count.textContent=chars.length.toLocaleString()+'文字 / '+txt.length.toLocaleString()+' UTF-16 code unit';allhex.textContent=bytes.map(b=>b.toString(16).padStart(2,'0').toUpperCase()).join(' ')||'—';table.innerHTML=chars.slice(0,200).map(c=>{const bs=[...enc.encode(c)],cp='U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0'),hex=bs.map(b=>b.toString(16).padStart(2,'0').toUpperCase()).join(' ');return'<div class="char-row"><span>'+esc(c)+'</span><span>'+cp+'</span><span>'+hex+'</span><span>'+bs.length+' byte</span></div>'}).join('')+(chars.length>200?'<div class="tool-note warn">先頭200文字まで表示しています。</div>':'');once()};input.addEventListener('input',run);$('[data-copy-hex]').onclick=()=>copy(allhex.textContent,$('[data-copy-hex]'));run()}
const PORTS=[[20,'TCP','FTP-data','FTPデータ転送'],[21,'TCP','FTP','FTP制御'],[22,'TCP','SSH','安全なリモート接続'],[23,'TCP','Telnet','平文リモート端末'],[25,'TCP','SMTP','メール送信'],[53,'TCP/UDP','DNS','名前解決'],[67,'UDP','DHCP Server','DHCPサーバー'],[68,'UDP','DHCP Client','DHCPクライアント'],[80,'TCP','HTTP','Web通信'],[110,'TCP','POP3','メール受信'],[123,'UDP','NTP','時刻同期'],[143,'TCP','IMAP','メール受信・管理'],[161,'UDP','SNMP','ネットワーク監視'],[162,'UDP','SNMP Trap','SNMP通知'],[389,'TCP/UDP','LDAP','ディレクトリサービス'],[443,'TCP/UDP','HTTPS','HTTPS。HTTP/3ではQUIC/UDPを使用'],[445,'TCP','SMB','Windowsファイル共有'],[465,'TCP','SMTPS','SMTP over TLSとして利用'],[514,'UDP/TCP','Syslog','ログ転送'],[587,'TCP','Submission','メール送信サブミッション'],[636,'TCP','LDAPS','LDAP over TLS'],[993,'TCP','IMAPS','IMAP over TLS'],[995,'TCP','POP3S','POP3 over TLS'],[1433,'TCP','MS SQL Server','Microsoft SQL Server'],[1521,'TCP','Oracle','Oracle Database'],[3306,'TCP','MySQL','MySQL'],[3389,'TCP/UDP','RDP','Remote Desktop Protocol'],[5432,'TCP','PostgreSQL','PostgreSQL'],[6379,'TCP','Redis','Redis'],[8080,'TCP','HTTP Alternate','HTTP代替ポートとしてよく使われる'],[8443,'TCP','HTTPS Alternate','HTTPS代替ポートとしてよく使われる']];function initPort(){const q=$('[data-port-search]'),list=$('[data-port-list]'),msg=$('[data-port-msg]');const run=()=>{const s=q.value.trim().toLowerCase(),num=/^\d+$/.test(s)?Number(s):null;let r=PORTS.filter(x=>!s||x[0]===num||x[2].toLowerCase().includes(s)||x[3].toLowerCase().includes(s)||x[1].toLowerCase().includes(s));if(num!==null)r.sort((a,b)=>(a[0]===num?-1:0)-(b[0]===num?-1:0));r=r.slice(0,50);list.innerHTML=r.map(x=>'<div class="port-item"><div class="port-num">'+x[0]+'<span>'+x[1]+'</span></div><div><strong>'+esc(x[2])+'</strong><span>'+esc(x[3])+'</span></div></div>').join('');msg.textContent=r.length?r.length+'件表示':'代表的な一覧には見つかりません。IANA Service Name and Transport Protocol Port Number Registryで確認してください。';once()};q.addEventListener('input',run);$$('[data-port-example]').forEach(b=>b.onclick=()=>{q.value=b.dataset.portExample;run()});run()}
function initURL(){const input=$('[data-url-input]'),err=$('[data-error]'),query=$('[data-query-list]');const set=(k,v)=>{$('[data-url-'+k+']').textContent=v||'—'};const run=()=>{try{const raw=input.value.trim();if(!raw)throw Error('URLを入力してください');const u=new URL(raw);err.classList.remove('show');set('scheme',u.protocol.replace(':',''));set('hostname',u.hostname);set('port',u.port||((u.protocol==='https:')?'443':(u.protocol==='http:')?'80':'既定'));set('path',u.pathname||'/');set('query',u.search||'—');set('fragment',u.hash||'—');set('origin',u.origin);set('userinfo',u.username?(decodeURIComponent(u.username)+(u.password?' : パスワードあり（非表示）':'')):'—');const rows=[...u.searchParams.entries()];query.innerHTML=rows.length?rows.map(([k,v])=>'<div class="query-item"><b>'+esc(k)+'</b><span>'+esc(v)+'</span></div>').join(''):'<div class="tool-note">クエリパラメータはありません。</div>';once()}catch(e){err.textContent='URLとして読めません。https://example.com/path?key=value のように入力してください。';err.classList.add('show');['scheme','hostname','port','path','query','fragment','origin','userinfo'].forEach(k=>set(k,'—'));query.innerHTML=''}};input.addEventListener('input',run);$$('[data-url-example]').forEach(b=>b.onclick=()=>{input.value=b.dataset.urlExample;run()});run()}
